// Manual fee calculation test
function feeMinor(lineTotalsMinor, rateBasisPoints) {
  const total = lineTotalsMinor.reduce((sum, value) => sum + value, 0);
  return Math.floor((total * rateBasisPoints) / 10_000) + bankersAdjustment(total, rateBasisPoints);
}

function bankersAdjustment(total, rateBasisPoints) {
  const remainder = (total * rateBasisPoints) % 10_000;
  if (remainder === 5_000) return (Math.floor((total * rateBasisPoints) / 10_000) % 2 === 0) ? 0 : 1;
  return remainder > 5_000 ? 1 : 0;
}

// Test banker's rounding with odd quotient (should round up)
console.log("Test: 20001 * 50 / 10000");
const total1 = 20001;
const rate1 = 50;
const product1 = total1 * rate1;
console.log(`  Product: ${product1}`);
console.log(`  Floor division: ${Math.floor(product1 / 10_000)}`);
console.log(`  Remainder: ${product1 % 10_000}`);
console.log(`  Result: ${feeMinor([20001], 50)}`);
console.log(`  Expected: 101 (odd quotient 100, remainder 5000, rounds up)\n`);

// Test banker's rounding with even quotient (should round down)
console.log("Test: 20000 * 50 / 10000");
const total2 = 20000;
const rate2 = 50;
const product2 = total2 * rate2;
console.log(`  Product: ${product2}`);
console.log(`  Floor division: ${Math.floor(product2 / 10_000)}`);
console.log(`  Remainder: ${product2 % 10_000}`);
console.log(`  Result: ${feeMinor([20000], 50)}`);
console.log(`  Expected: 100 (even quotient, no rounding needed)`);
EOF
